"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["36136"],{56589(i){i.exports=JSON.parse('{"tag":{"label":"Rabbits","permalink":"/docs/tags/rabbits","allTagsPath":"/docs/tags","count":39,"items":[{"id":"general-care/health-and-medical/skin-issues","title":"A Guide to Common Skin Issues in Small Pets","description":"A comprehensive guide to identifying, preventing, and treating common skin problems in small exotic pets, including urine scald, mites, ringworm, and bacterial infections, with species-specific advice.","permalink":"/docs/general-care/health-and-medical/skin-issues"},{"id":"Rabbits/getting-started/basic-care","title":"Basic Care for Pet Rabbits","description":"An essential guide to the fundamental aspects of pet rabbit care, including diet, housing, exercise, and social needs.","permalink":"/docs/Rabbits/getting-started/basic-care"},{"id":"guinea-pigs/illnesses-and-conditions/bordetella-in-guinea-pigs","title":"Bordetella in Guinea Pigs","description":"Bordetella bronchiseptica is a bacterium that causes respiratory disease in a variety of animals. While it is most commonly known as a cause of \'kennel cough\' in dogs, it can be a life-threatening...","permalink":"/docs/guinea-pigs/illnesses-and-conditions/bordetella-in-guinea-pigs"},{"id":"Rabbits/illnesses-and-conditions/coccidia-in-rabbits","title":"Coccidia in Rabbits","description":"A comprehensive guide to coccidiosis in rabbits \u2014 causes, symptoms, diagnosis, treatment, and prevention of this common parasitic infection.","permalink":"/docs/Rabbits/illnesses-and-conditions/coccidia-in-rabbits"},{"id":"Rabbits/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Rabbits","description":"An overview of the most common and serious health issues affecting pet rabbits, including the critical emergencies of GI stasis, the importance of dental health, and the high rate of uterine cancer in unspayed females.","permalink":"/docs/Rabbits/illnesses-and-conditions/common-health-issues"},{"id":"general-care/safety/dangerous-plants","title":"Dangerous Plants for Small Pets: A Regional Guide","description":"Global dangerous plants infographic","permalink":"/docs/general-care/safety/dangerous-plants"},{"id":"Rabbits/health-and-wellness/dental-health","title":"Dental Health in Rabbits","description":"An in-depth guide to dental disease in rabbits, explaining why it is so common, how to recognize the signs of oral pain, and the absolute necessity of a hay-based diet for prevention.","permalink":"/docs/Rabbits/health-and-wellness/dental-health"},{"id":"Rabbits/illnesses-and-conditions/diabetes-in-rabbits","title":"Diabetes in Pet Rabbits","description":"A comprehensive guide to diabetes in rabbits \u2014 causes, symptoms, diagnosis, and management of this rare but serious metabolic condition.","permalink":"/docs/Rabbits/illnesses-and-conditions/diabetes-in-rabbits"},{"id":"Rabbits/illnesses-and-conditions/e-cuniculi-in-rabbits","title":"E. cuniculi in Rabbits","description":"A comprehensive guide to Encephalitozoon cuniculi in rabbits \u2014 transmission, signs, diagnosis, treatment, and prevention of this common neurological parasite.","permalink":"/docs/Rabbits/illnesses-and-conditions/e-cuniculi-in-rabbits"},{"id":"Rabbits/illnesses-and-conditions/ear-infections-in-rabbits","title":"Ear Infections in Rabbits","description":"A guide to ear infections in rabbits \u2014 types, causes, symptoms, diagnosis, treatment, and prevention of otitis in pet rabbits.","permalink":"/docs/Rabbits/illnesses-and-conditions/ear-infections-in-rabbits"},{"id":"general-care/health-and-medical/entropion","title":"Entropion in Small Pets","description":"A comprehensive guide to entropion \u2014 the inward rolling of the eyelid \u2014 in small pets including rabbits, hamsters, guinea pigs, and rats. Covers causes, clinical signs, diagnosis, and treatment options.","permalink":"/docs/general-care/health-and-medical/entropion"},{"id":"Rabbits/care-and-husbandry/essential-supplies","title":"Essential Supplies for Your Rabbit Companion","description":"Bringing a rabbit into your home is a long-term commitment, and providing the right supplies is the first step to ensuring a happy, healthy life for your new friend. Rabbits have specific needs that...","permalink":"/docs/Rabbits/care-and-husbandry/essential-supplies"},{"id":"Rabbits/health-and-wellness/eye-and-vision-issues","title":"Eye & Vision Issues in Rabbits","description":"A guide to common eye and vision issues in rabbits, focusing on the critical link between weepy eyes (epiphora) and underlying dental disease, as well as other conditions like ulcers and abscesses.","permalink":"/docs/Rabbits/health-and-wellness/eye-and-vision-issues"},{"id":"Rabbits/illnesses-and-conditions/fly-strike-in-rabbits","title":"Fly Strike (Myiasis) in Rabbits: A Veterinary Emergency","description":"Fly strike, also known as myiasis, is a devastating and rapidly progressing condition that is a true veterinary emergency. It occurs when flies, typically blowflies, lay eggs on a rabbit. These eggs...","permalink":"/docs/Rabbits/illnesses-and-conditions/fly-strike-in-rabbits"},{"id":"Rabbits/health-and-wellness/gi-health","title":"Gastrointestinal (GI) Health in Rabbits","description":"An in-depth guide to the sensitive gastrointestinal (GI) system of rabbits, covering the causes and signs of the life-threatening emergencies GI stasis and bloat, and the critical role of hay.","permalink":"/docs/Rabbits/health-and-wellness/gi-health"},{"id":"Rabbits/illnesses-and-conditions/gi-issues-in-rabbits","title":"GI Issues in Rabbits","description":"For rabbit owners, understanding and preventing gastrointestinal (GI) issues is paramount to ensuring the health and happiness of their beloved pets. Rabbits have delicate digestive systems, and...","permalink":"/docs/Rabbits/illnesses-and-conditions/gi-issues-in-rabbits"},{"id":"Rabbits/care-and-husbandry/grooming","title":"Grooming Your Pet Rabbit","description":"A guide to the essential grooming needs of a pet rabbit, including brushing, nail trimming, and cleaning scent glands.","permalink":"/docs/Rabbits/care-and-husbandry/grooming"},{"id":"Rabbits/care-and-husbandry/habitat","title":"Habitat for Pet Rabbits","description":"A guide to creating the ideal indoor habitat for pet rabbits, focusing on space, safety, and enrichment to meet their environmental needs.","permalink":"/docs/Rabbits/care-and-husbandry/habitat"},{"id":"Rabbits/health-and-wellness/home-health-care-for-your-rabbit","title":"Home Health Care for Your Rabbit","description":"Caring for a rabbit can be a deeply rewarding experience, bringing joy and companionship to your home. These intelligent and social creatures, capable of living up to 12\u201315 years, thrive with proper care and attention [1]. Understanding their unique needs \u2014 from diet to dental health and disease prevention \u2014 is crucial for ensuring a long and happy life for your furry friend. This guide walks you through essential aspects of home health care for your rabbit.","permalink":"/docs/Rabbits/health-and-wellness/home-health-care-for-your-rabbit"},{"id":"general-care/daily-care/introductions-and-bonding","title":"Introductions and Bonding","description":"How to safely introduce small pets to each other \u2014 covering quarantine, scent swapping, neutral space introductions, and warning signs for all HALT species.","permalink":"/docs/general-care/daily-care/introductions-and-bonding"},{"id":"Rabbits/getting-started/is-a-rabbit-right-for-me","title":"Is a Rabbit Right for Me and My Family?","description":"Rabbits are among the most popular pets in the United States \u2014 and among the most frequently surrendered. The gap between expectation and reality is wide: many families bring home a rabbit imagining...","permalink":"/docs/Rabbits/getting-started/is-a-rabbit-right-for-me"},{"id":"Rabbits/breeds-and-genetics/know-your-rabbit-breeds","title":"Know Your Rabbit Breeds","description":"A guide to popular pet rabbit breeds recognized by the American Rabbit Breeders Association, including size, temperament, and care considerations.","permalink":"/docs/Rabbits/breeds-and-genetics/know-your-rabbit-breeds"},{"id":"general-care/health-and-medical/mastitis","title":"Mastitis in Small Pets","description":"An overview of mastitis, a painful infection of the mammary glands, in small pets. Learn to recognize the signs, understand the causes, and know when to seek immediate veterinary care.","permalink":"/docs/general-care/health-and-medical/mastitis"},{"id":"Rabbits/illnesses-and-conditions/maxfactor","title":"Max Factor Rabbits","description":"Max Factor rabbits are a rare and unique type of rabbit affected by a genetic mutation that results in unusual physical characteristics. These rabbits have striking appearances due to differences in their fur and limbs. It\u2019s said that the condition is named after a rabbit named Max who was known to have the condition, but not much is known about the defect or its origin. However, the mutation also affects their health and mobility, creating both challenges and specific care needs. Here\u2019s everything you need to know about Max Factor rabbits, from their characteristics to the ethics of breeding them.","permalink":"/docs/Rabbits/illnesses-and-conditions/maxfactor"},{"id":"general-care/health-and-medical/microphthalmia","title":"Microphthalmia in Small Pets","description":"A comprehensive guide to microphthalmia (abnormally small eyes) in small pets, covering its genetic causes, species-specific presentations in rabbits, ferrets, hamsters, guinea pigs, and rats, and how to manage affected animals.","permalink":"/docs/general-care/health-and-medical/microphthalmia"},{"id":"Rabbits/illnesses-and-conditions/neurologic-issues-in-rabbits","title":"Neurologic Issues in Rabbits","description":"A guide to neurological conditions in rabbits \u2014 causes, symptoms, diagnosis, treatment, and care for rabbits with neurologic disease.","permalink":"/docs/Rabbits/illnesses-and-conditions/neurologic-issues-in-rabbits"},{"id":"Rabbits/care-and-husbandry/nutrition","title":"Nutrition for Pet Rabbits","description":"A detailed guide to the correct diet for a pet rabbit, emphasizing the importance of hay and outlining the proper portions of greens, pellets, and treats.","permalink":"/docs/Rabbits/care-and-husbandry/nutrition"},{"id":"Rabbits/health-and-wellness/parasites","title":"Parasites in Rabbits","description":"A guide to common parasites affecting rabbits, including the severe ear and fur mites, and the neurological parasite E. cuniculi, a primary cause of head tilt.","permalink":"/docs/Rabbits/health-and-wellness/parasites"},{"id":"Rabbits/illnesses-and-conditions/parasites-in-rabbits","title":"Parasites in Rabbits","description":"A comprehensive overview of common internal and external parasites in rabbits, including mites, fleas, ticks, worms, and protozoa like E. cuniculi and coccidia.","permalink":"/docs/Rabbits/illnesses-and-conditions/parasites-in-rabbits"},{"id":"Rabbits/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Rabbit","description":"Rabbits are intelligent, curious animals that need daily mental and physical stimulation. Learn how to play with and train your rabbit using positive reinforcement.","permalink":"/docs/Rabbits/care-and-husbandry/playing-and-training"},{"id":"Rabbits/care-and-husbandry/proper-handling","title":"Proper Handling of Pet Rabbits","description":"A guide to the correct and safe methods for handling a pet rabbit, focusing on building trust and preventing injury.","permalink":"/docs/Rabbits/care-and-husbandry/proper-handling"},{"id":"Rabbits/breeds-and-genetics/coat-color-genetics","title":"Rabbit Coat Color Genetics","description":"An introduction to rabbit coat color genetics, covering the major gene loci, common color patterns, and the Blue-Eyed White (Vienna) gene.","permalink":"/docs/Rabbits/breeds-and-genetics/coat-color-genetics"},{"id":"Rabbits/health-and-wellness/respiratory-issues","title":"Respiratory Issues in Rabbits (\\"Snuffles\\")","description":"An in-depth guide to upper respiratory infections (Snuffles) in rabbits, caused by Pasteurella multocida and other bacteria, covering the signs, progression, and treatment of this common and often chronic condition.","permalink":"/docs/Rabbits/health-and-wellness/respiratory-issues"},{"id":"general-care/daily-care/safe-treats","title":"Safe Treats for Small Pets","description":"A comprehensive guide to safe and unsafe treats for all small pet species, including rabbits, guinea pigs, rats, hamsters, gerbils, chinchillas, ferrets, hedgehogs, mice, and degus.","permalink":"/docs/general-care/daily-care/safe-treats"},{"id":"Rabbits/breeds-and-genetics/sexing-your-rabbit","title":"Sexing Your Pet Rabbit","description":"A clear guide on how to determine the sex of a pet rabbit by examining their genital anatomy, essential for proper care and preventing unwanted litters.","permalink":"/docs/Rabbits/breeds-and-genetics/sexing-your-rabbit"},{"id":"general-care/daily-care/outdoor-safety","title":"Taking Your Small Pet Outside Safely","description":"Outdoor safety infographic for small pets","permalink":"/docs/general-care/daily-care/outdoor-safety"},{"id":"Rabbits/health-and-wellness/rvhd2-vaccination","title":"The Importance of Vaccinating Your Rabbit Against RVHD2","description":"As a responsible rabbit owner, safeguarding your companion from preventable diseases is a top priority. One of the most serious threats to domestic rabbits today is Rabbit Hemorrhagic Disease Virus 2...","permalink":"/docs/Rabbits/health-and-wellness/rvhd2-vaccination"},{"id":"Rabbits/health-and-wellness/understanding-rabbit-behavior","title":"Understanding Rabbit Behavior: A Guide for Owners","description":"Rabbits are highly expressive animals whose body language is subtle but rich. Understanding what your rabbit is communicating is key to building a trusting relationship and catching health problems early.","permalink":"/docs/Rabbits/health-and-wellness/understanding-rabbit-behavior"},{"id":"Rabbits/illnesses-and-conditions/urinary-and-bladder-issues","title":"Urinary and Bladder Issues in Rabbits","description":"An in-depth guide to urinary and bladder issues in rabbits, focusing on the causes and management of excess calcium in the urine (sludge) and the formation of bladder stones.","permalink":"/docs/Rabbits/illnesses-and-conditions/urinary-and-bladder-issues"}],"unlisted":false}}')}}]);